typedef struct CutsceneCamKey {
    u8 pad_00[0xC];
    s8 flag;                    /* 0x0C: read as a signed byte (lb) */
    u8 pad_0D[0x3];
    f32 values[4];              /* 0x10: rotation angles x, y, z, then the unscaled value */
} CutsceneCamKey;

typedef struct {
    u8 pad_00[0x38];
    s32 key_index;              /* 0x38 */
    u8 pad_3C[0x18];
    CutsceneCamKey *keys;       /* 0x54: 32-byte key rows */
} CutsceneCamCtl;

typedef struct {
    u8 pad_00[0xB0];
    f32 unkB0;                  /* 0xB0 */
} CutsceneCamVars;

typedef struct {
    u8 pad_000[0x350];
    Vec4f matrix[3];            /* 0x350: view rotation rows, x/y/z per row */
} CameraBlock;

/* Builds the camera view matrices from the current camera entry and returns the entry's flag byte. */
unsigned char apply_cutscene_camera_key(void) {
    CutsceneCamCtl *d = (CutsceneCamCtl *)cutscene_state;
    int idx = d->key_index;
    CutsceneCamKey *e = d->keys + idx;
    f32 *p = e->values;
    CameraBlock *cc;
    float f0;
    CutsceneCamVars *b = (CutsceneCamVars *)render_view_params;
    char *c;
    unsigned char r;
    float m[16];
    float v[4];
    r = e->flag;
    f0 = p[3];
    b->unkB0 = f0;
    if (gCheats[0] != 0) {
        b->unkB0 = f0 * big_head_cutscene_fov_scale;
    }
    UpdateViewContext();
    c = g_debug_camera;
    qcopy(c, e);
    sceVu0UnitMatrix(m);
    sceVu0RotMatrixX(m, m, e->values[0]);
    sceVu0RotMatrixY(m, m, p[1]);
    sceVu0RotMatrixZ(m, m, p[2]);
    cc = (CameraBlock *)(c - 0x140);
    cc->matrix[0].x = -m[8];
    cc->matrix[1].x = -m[0];
    cc->matrix[2].x = m[4];
    cc->matrix[0].y = -m[9];
    cc->matrix[1].y = -m[1];
    cc->matrix[2].y = m[5];
    cc->matrix[0].z = -m[10];
    cc->matrix[1].z = -m[2];
    cc->matrix[2].z = m[6];
    if (draw_map51_m[0] != 0) {
        FastVecCross(c + 0x220, c + 0x230, c + 0x210);
    }
    if (gCheats[0] != 0) {
        float f = *(float *)&big_head_cutscene_camera_pullback;
        if (f != 0.0f) {
            qcopy(v, c + 0x210);
            vec_scale_to_length(v, v, f);
            FastVecSub(c, c, v);
        }
    }
    return r;
}
