#define ITMR (((short *)D_L00_0015F700)[3])

/* Per-frame slideshow update: fades in, shows each image for its time, then moves to the next. */
void update_slideshow(void) {
    int s0, t, i, r, one;
    int *src, *dst;
    float f;
    update_audio_stream_until_idle(0);
    f = *(float *)&gFadeLvl - 0.05f;
    *(float *)&gFadeLvl = f;
    if (f < 0.0f) {
        *(float *)&gFadeLvl = 0.0f;
    }
    s0 = *(unsigned char *)(pad_globals_base + 0x2CF2) == 0x41;
    one = 1;
    if (IST == 0) {
        if (ITMR >= slideshow_slide_durations[IIDX] - 0x24) {
            if (*(short *)(help_stats_base + 0x100BD) != 0) {
                update_audio_stream_until_idle(1);
            }
            if (!s0 && IIDX == 0x29) {
            quit:
                end_slideshow();
                return;
            }
            if (IIDX >= 0x2D) goto quit;
            ICNT = -1;
            IST = 1;
        }
    } else if (IST == one) {
        VU1_syncChain(1);
        t = ICNT;
        if (t < 0x20) {
            src = (int *)slideshow[3];
            dst = (int *)slideshow[2];
            src += t;
            dst += t;
            for (i = 0; i <= 0x37FFF; i += 0x20) {
                *dst = *src;
                dst += 0x20;
                src += 0x20;
            }
        } else if (t >= 0x24) {
            if (!s0) {
                if (IIDX == 8) {
                    IIDX = 0x11;
                    ITMR = 0x1590;
                }
            } else {
                if (IIDX == 0x11) {
                    IIDX = 0x1B;
                    ITMR = 0x2238;
                }
                if (IIDX == 0x27) {
                    IIDX = 0x29;
                    ITMR = 0x32B4;
                }
            }
            IST = 0;
            ICNT = -1;
            IIDX = IIDX + 1;
            r = IIDX % 20;
            if (pal_mode != 0) {
                start_audio_stream_read(slideshow[3], disc_table.alt[r].a, disc_table.alt[r].b);
            } else {
                start_audio_stream_read(slideshow[3], disc_table.normal[r].a, disc_table.normal[r].b);
            }
        }
    }
    ICNT = ICNT + 1;
    ITMR = ITMR + 1;
    if (*(int *)(pad_globals_base + 0x2604) & 0x800) {
        end_slideshow();
    }
    sound_update();
}
